   163  // We don't use strlen() in libc since it's not guaranteed to be async
   164  // signal safe.
   165  static size_t StrLen(const char *str) {
   166    size_t len = 0;
   167    while (*str != '\0') {
   168      ++str;
   169      ++len;
   170    }
   171    return len;
   172  }
