   346  // A convenient wrapper arount MaybeAppendWithLength().
   347  static bool MaybeAppend(State *state, const char * const str) {
   348    if (state->append) {
   349      size_t length = StrLen(str);
   350      MaybeAppendWithLength(state, str, static_cast<ssize_t>(length));
   351    }
   352    return true;
   353  }
