   938    *state = copy;
   939
   940    if (ParseCharClass(state, "OPRCG") && ParseType(state)) {
   941      return true;
   942    }
   943    *state = copy;
   944
   945    if (ParseTwoCharToken(state, "Dp") && ParseType(state)) {
